export const MusicPlayer: React.FC<MusicPlayerProps> = ({
  track,
  autoPlay = false,
  showTrackInfo = true,
  showVolumeControl = true,
  showProgress = true,
  showControls = true,
  showSkipButtons = true,
  variant = 'default',
  size = 'md',
  theme = 'light',
  platform = 'default',
  className = '',
  style = {},
  onEnded,
  onPlay,
  onPause,
  onNext,
  onPrevious,
}) => {
  // Audio state
  const audioRef = useRef<HTMLAudioElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.7);
  const [isMuted, setIsMuted] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [bufferProgress, setBufferProgress] = useState(0);

  // Initialize audio element
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    // Set up event listeners
    const handleTimeUpdate = () => setCurrentTime(audio.currentTime);
    const handleDurationChange = () => setDuration(audio.duration);
    const handleEnded = () => {
      setIsPlaying(false);
      if (onEnded) onEnded();
    };
    const handlePlay = () => {
      setIsPlaying(true);
      if (onPlay) onPlay();
    };
    const handlePause = () => {
      setIsPlaying(false);
      if (onPause) onPause();
    };
    const handleLoadedData = () => setIsLoaded(true);
    const handleProgress = () => {
      if (audio.buffered.length > 0) {
        const bufferedEnd = audio.buffered.end(audio.buffered.length - 1);
        setBufferProgress((bufferedEnd / audio.duration) * 100);
      }
    };

    // Add event listeners
    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('durationchange', handleDurationChange);
    audio.addEventListener('ended', handleEnded);
    audio.addEventListener('play', handlePlay);
    audio.addEventListener('pause', handlePause);
    audio.addEventListener('loadeddata', handleLoadedData);
    audio.addEventListener('progress', handleProgress);

    // Set initial volume
    audio.volume = volume;
    audio.muted = isMuted;

    // Autoplay if enabled
    if (autoPlay && isLoaded) {
      audio.play().catch(error => console.error('Autoplay failed:', error));
    }

    // Clean up event listeners
    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('durationchange', handleDurationChange);
      audio.removeEventListener('ended', handleEnded);
      audio.removeEventListener('play', handlePlay);
      audio.removeEventListener('pause', handlePause);
      audio.removeEventListener('loadeddata', handleLoadedData);
      audio.removeEventListener('progress', handleProgress);
    };
  }, [autoPlay, isLoaded, onEnded, onPause, onPlay, volume, isMuted]);

  // Update audio source when track changes
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    // Reset state
    setIsPlaying(false);
    setCurrentTime(0);
    setDuration(0);
    setIsLoaded(false);
    setBufferProgress(0);

    // Load new track
    audio.src = track.src;
    audio.load();
  }, [track]);

  // Playback controls
  const togglePlayPause = () => {
    const audio = audioRef.current;
    if (!audio) return;

    if (isPlaying) {
      audio.pause();
    } else {
      audio.play().catch(error => console.error('Play failed:', error));
    }
  };

  const handleSeek = (value: number[]) => {
    const audio = audioRef.current;
    if (!audio) return;

    audio.currentTime = value[0];
    setCurrentTime(value[0]);
  };

  const handleVolumeChange = (value: number[]) => {
    const audio = audioRef.current;
    if (!audio) return;

    const newVolume = value[0];
    setVolume(newVolume);
    audio.volume = newVolume;

    // If volume is set to 0, mute the audio
    if (newVolume === 0) {
      setIsMuted(true);
      audio.muted = true;
    } else if (isMuted) {
      setIsMuted(false);
      audio.muted = false;
    }
  };

  const toggleMute = () => {
    const audio = audioRef.current;
    if (!audio) return;

    const newMutedState = !isMuted;
    setIsMuted(newMutedState);
    audio.muted = newMutedState;
  };

  const handlePrevious = () => {
    if (onPrevious) onPrevious();
  };

  const handleNext = () => {
    if (onNext) onNext();
  };

  // Determine artwork size based on player size and variant
  const getArtworkSize = (variant: MusicPlayerVariant, size: MusicPlayerSize): AlbumArtworkSize => {
    if (variant === 'compact') {
      return size === 'sm' ? 'xs' : size === 'md' ? 'sm' : 'sm';
    } else if (variant === 'minimal') {
      return size === 'sm' ? 'sm' : size === 'md' ? 'base' : 'md';
    } else if (variant === 'expanded') {
      return size === 'sm' ? 'md' : size === 'md' ? 'lg' : 'lg';
    } else {
      return size === 'sm' ? 'base' : size === 'md' ? 'md' : size === 'lg' ? 'lg' : 'auto';
    }
  };

  return (
    <PlayerContainer
      $variant={variant}
      $size={size}
      $theme={theme}
      $platform={platform}
      className={`music-player ${className}`}
      style={style}
    >
      {/* Hidden audio element */}
      <audio ref={audioRef} />

      {/* Apple Music Progress Bar - Only show at top for Apple Music compact variant */}
      {showProgress && variant === 'compact' && platform === 'apple' && (
        <Slider
          value={[currentTime]}
          min={0}
          max={duration || 100}
          step={0.1}
          onValueChange={handleSeek}
          size="sm"
          variant="minimal"
          bufferValue={duration * (bufferProgress / 100)}
          showBuffer={true}
          disabled={!isLoaded}
          platform={platform}
          thumbVisibility="hover"
          style={{ margin: 0 }}
          aria-label="Track progress"
        />
      )}

      <CompactContainer $platform={platform}>
        {/* Track info section */}
        {showTrackInfo && (
          <TrackInfoContainer $variant={variant} $platform={platform}>
            <AlbumArtwork
              image={track.coverArt}
              name={track.title}
              size={getArtworkSize(variant, size)}
              shadow={variant !== 'compact'}
              platform={platform}
              style={{ flexShrink: 0 }}
            />
            <TrackDetails $variant={variant} $platform={platform}>
              <MetadataLabel
                text={track.title}
                truncate={true}
                maxLength={variant === 'compact' ? 16 : 30}
                as="h3"
                style={{
                  fontWeight: 600,
                  fontSize: size === 'sm' ? '14px' : size === 'md' ? '16px' : '18px',
                  margin: 0,
                  lineHeight: variant === 'compact' ? '1.2' : 'normal',
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  ...(platform === 'spotify' && {
                    fontFamily: 'Circular, Helvetica, Arial, sans-serif',
                    fontWeight: 700,
                  }),
                  ...(platform === 'apple' && {
                    fontFamily: 'SF Pro Display, -apple-system, BlinkMacSystemFont, sans-serif',
                    fontWeight: 600,
                  }),
                  ...(platform === 'tidal' && {
                    fontFamily: 'Gotham, Helvetica, Arial, sans-serif',
                    fontWeight: 500,
                    letterSpacing: '0.5px',
                  }),
                }}
              />
              <ArtistLabel
                artists={track.artist}
                truncate={true}
                maxLength={variant === 'compact' ? 16 : 30}
                style={{
                  fontSize: size === 'sm' ? '12px' : size === 'md' ? '14px' : '16px',
                  color: 'var(--color-text-muted, #6b7280)',
                  lineHeight: variant === 'compact' ? '1.2' : 'normal',
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  ...(platform === 'spotify' && {
                    fontFamily: 'Circular, Helvetica, Arial, sans-serif',
                    color: 'rgba(255, 255, 255, 0.7)',
                    fontSize: size === 'sm' ? '11px' : size === 'md' ? '13px' : '15px',
                  }),
                  ...(platform === 'apple' && {
                    fontFamily: 'SF Pro Text, -apple-system, BlinkMacSystemFont, sans-serif',
                    color: theme === 'dark' ? 'rgba(255, 255, 255, 0.6)' : 'rgba(0, 0, 0, 0.6)',
                  }),
                  ...(platform === 'tidal' && {
                    fontFamily: 'Gotham, Helvetica, Arial, sans-serif',
                    color: 'rgba(255, 255, 255, 0.7)',
                    letterSpacing: '0.3px',
                    textTransform: 'uppercase',
                    fontSize: size === 'sm' ? '10px' : size === 'md' ? '11px' : '12px',
                  }),
                }}
              />
              {track.album && variant !== 'compact' && (
                <MetadataLabel
                  text={track.album}
                  truncate={true}
                  maxLength={30}
                  style={{
                    fontSize: size === 'sm' ? '11px' : size === 'md' ? '12px' : '14px',
                    color: 'var(--color-text-muted, #6b7280)',
                    fontStyle: 'italic',
                    ...(platform === 'spotify' && {
                      fontFamily: 'Circular, Helvetica, Arial, sans-serif',
                      color: 'rgba(255, 255, 255, 0.6)',
                      fontStyle: 'normal',
                    }),
                    ...(platform === 'apple' && {
                      fontFamily: 'SF Pro Text, -apple-system, BlinkMacSystemFont, sans-serif',
                      color: theme === 'dark' ? 'rgba(255, 255, 255, 0.5)' : 'rgba(0, 0, 0, 0.5)',
                    }),
                    ...(platform === 'tidal' && {
                      fontFamily: 'Gotham, Helvetica, Arial, sans-serif',
                      color: 'rgba(255, 255, 255, 0.6)',
                      fontStyle: 'normal',
                      letterSpacing: '0.3px',
                    }),
                  }}
                />
              )}
            </TrackDetails>
          </TrackInfoContainer>
        )}

        {/* Spotify Progress Bar - Show inline for Spotify compact variant */}
        {showProgress && variant === 'compact' && platform === 'spotify' && (
          <CompactProgressContainer $platform={platform}>
            <Slider
              value={[currentTime]}
              min={0}
              max={duration || 100}
              step={0.1}
              onValueChange={handleSeek}
              size="sm"
              variant="minimal"
              bufferValue={duration * (bufferProgress / 100)}
              showBuffer={true}
              disabled={!isLoaded}
              platform={platform}
              thumbVisibility="hover"
              style={{ margin: 0 }}
              aria-label="Track progress"
            />
          </CompactProgressContainer>
        )}

        {/* Progress bar - Only show in non-compact variants or if explicitly requested */}
        {showProgress && variant !== 'compact' && (
          <ProgressContainer $platform={platform}>
            <Slider
              value={[currentTime]}
              min={0}
              max={duration || 100}
              step={0.1}
              onValueChange={handleSeek}
              size={size === 'sm' ? 'sm' : size === 'md' ? 'md' : 'lg'}
              variant={platform === 'spotify' || platform === 'apple' ? 'minimal' : 'default'}
              bufferValue={duration * (bufferProgress / 100)}
              showBuffer={true}
              disabled={!isLoaded}
              platform={platform}
              thumbVisibility={platform === 'spotify' || platform === 'apple' ? 'hover' : 'always'}
              aria-label="Track progress"
            />
            <TimeDisplay $platform={platform}>
              <Timestamp value={currentTime} format="duration" variant="muted" size="sm" />
              <Timestamp value={duration || 0} format="duration" variant="muted" size="sm" />
            </TimeDisplay>
          </ProgressContainer>
        )}

        {/* Controls section */}
        {showControls && (
          <ControlsContainer $variant={variant} $platform={platform}>
            {variant === 'compact' ? (
              <>
                {/* For Apple Music, show timestamp before controls */}
                {platform === 'apple' && showProgress && (
                  <Timestamp
                    value={currentTime}
                    format="duration"
                    variant="muted"
                    size="sm"
                    style={{
                      marginRight: '8px',
                      fontFamily: 'SF Pro Text, -apple-system, BlinkMacSystemFont, sans-serif',
                      fontSize: '12px',
                    }}
                  />
                )}

                {showSkipButtons && (
                  <IconButton
                    icon={BiSkipPrevious}
                    aria-label="Previous track"
                    onClick={handlePrevious}
                    variant="ghost"
                    size="sm"
                    platform={platform}
                    style={{ padding: '4px' }}
                    disabled={!isLoaded}
                  />
                )}
                <IconButton
                  icon={isPlaying ? FiPause : FiPlay}
                  aria-label={isPlaying ? 'Pause' : 'Play'}
                  onClick={togglePlayPause}
                  variant={platform === 'spotify' ? 'ghost' : 'primary'}
                  size="sm"
                  disabled={!isLoaded}
                  platform={platform}
                  style={{ padding: '4px' }}
                />
                {showSkipButtons && (
                  <IconButton
                    icon={BiSkipNext}
                    aria-label="Next track"
                    onClick={handleNext}
                    variant="ghost"
                    size="sm"
                    platform={platform}
                    style={{ padding: '4px' }}
                    disabled={!isLoaded}
                  />
                )}

                {/* For compact variant, show volume button without slider */}
                {showVolumeControl && (
                  <IconButton
                    icon={isMuted || volume === 0 ? FiVolumeX : FiVolume2}
                    aria-label={isMuted ? 'Unmute' : 'Mute'}
                    onClick={toggleMute}
                    variant="ghost"
                    size="sm"
                    platform={platform}
                    isEnabled={!isMuted && volume > 0}
                  />
                )}

                {/* For Spotify, show timestamp after controls */}
                {platform === 'spotify' && showProgress && (
                  <Timestamp
                    value={currentTime}
                    format="duration"
                    variant="muted"
                    size="sm"
                    style={{
                      marginLeft: '8px',
                      fontFamily: 'Circular, Helvetica, Arial, sans-serif',
                      fontSize: '11px',
                      color: 'rgba(255, 255, 255, 0.6)',
                    }}
                  />
                )}
              </>
            ) : (
              <PlaybackControlsContainer $platform={platform}>
                {showSkipButtons && (
                  <IconButton
                    icon={BiSkipPrevious}
                    aria-label="Previous track"
                    onClick={handlePrevious}
                    variant="ghost"
                    size={size === 'sm' ? 'sm' : size === 'md' ? 'md' : 'lg'}
                    platform={platform}
                  />
                )}
                <IconButton
                  icon={isPlaying ? FiPause : FiPlay}
                  aria-label={isPlaying ? 'Pause' : 'Play'}
                  onClick={togglePlayPause}
                  variant="primary"
                  size={size === 'sm' ? 'sm' : size === 'md' ? 'md' : 'lg'}
                  disabled={!isLoaded}
                  platform={platform}
                />
                {showSkipButtons && (
                  <IconButton
                    icon={BiSkipNext}
                    aria-label="Next track"
                    onClick={handleNext}
                    variant="ghost"
                    size={size === 'sm' ? 'sm' : size === 'md' ? 'md' : 'lg'}
                    platform={platform}
                  />
                )}
              </PlaybackControlsContainer>
            )}
          </ControlsContainer>
        )}
      </CompactContainer>

      {/* Volume control - Only show in non-compact variants */}
      {showVolumeControl && variant !== 'compact' && (
        <VolumeContainer $variant={variant} $platform={platform}>
          <IconButton
            icon={isMuted || volume === 0 ? FiVolumeX : FiVolume2}
            aria-label={isMuted ? 'Unmute' : 'Mute'}
            onClick={toggleMute}
            variant="ghost"
            size={size === 'sm' ? 'sm' : 'md'}
            platform={platform}
            isEnabled={!isMuted && volume > 0}
          />
          <Slider
            value={[isMuted ? 0 : volume]}
            min={0}
            max={1}
            step={0.01}
            onValueChange={handleVolumeChange}
            size="sm"
            variant={platform === 'spotify' || platform === 'apple' ? 'minimal' : 'minimal'}
            platform={platform}
            thumbVisibility={platform === 'spotify' || platform === 'apple' ? 'hover' : 'always'}
            aria-label="Volume"
          />
        </VolumeContainer>
      )}
    </PlayerContainer>
  );
};

export default MusicPlayer;

'use client';

import React, { useCallback, useEffect, useState, useRef } from 'react';
import * as RadixSlider from '@radix-ui/react-slider';
import styled, { css, keyframes } from 'styled-components';

/**
 * Platform variants for styling
 */
export type SliderPlatform = 'default' | 'spotify' | 'apple' | 'tidal' | 'custom';

/**
 * Slider size variants
 */
export type SliderSize = 'sm' | 'md' | 'lg';

/**
 * Slider variant styles
 */
export type SliderVariant = 'default' | 'minimal' | 'gradient' | 'custom';

/**
 * Slider orientation
 */
export type SliderOrientation = 'horizontal' | 'vertical';

/**
 * Thumb visibility options
 */
export type ThumbVisibility = 'always' | 'hover' | 'active' | 'never';

/**
 * Thumb variant styles
 */
export type ThumbVariant = 'default' | 'dot' | 'line' | 'square' | 'custom';

/**
 * Slider component props
 */
export interface SliderProps {
  /**
   * Current value of the slider
   */
  value: number[];

  /**
   * Callback when the value changes
   */
  onValueChange?: (value: number[]) => void;

  /**
   * Callback when the value change is committed (on drag end)
   */
  onValueCommit?: (value: number[]) => void;

  /**
   * Minimum value
   * @default 0
   */
  min?: number;

  /**
   * Maximum value
   * @default 100
   */
  max?: number;

  /**
   * Step value
   * @default 1
   */
  step?: number;

  /**
   * Size variant
   * @default 'md'
   */
  size?: SliderSize;

  /**
   * Style variant
   * @default 'default'
   */
  variant?: SliderVariant;

  /**
   * Thumb variant
   * @default 'default'
   */
  thumbVariant?: ThumbVariant;

  /**
   * Thumb visibility
   * @default 'always'
   */
  thumbVisibility?: ThumbVisibility;

  /**
   * Orientation of the slider
   * @default 'horizontal'
   */
  orientation?: SliderOrientation;

  /**
   * Whether the slider is disabled
   * @default false
   */
  disabled?: boolean;

  /**
   * Whether to show the thumb tooltip
   * @default false
   */
  showTooltip?: boolean;

  /**
   * Format function for the tooltip value
   */
  formatTooltip?: (value: number) => string;

  /**
   * Whether to animate value changes
   * @default true
   */
  animate?: boolean;

  /**
   * Whether to optimize for performance
   * @default false
   */
  optimizePerformance?: boolean;

  /**
   * Whether to show tick marks
   * @default false
   */
  showTicks?: boolean;

  /**
   * Number of tick marks to show
   * @default 5
   */
  tickCount?: number;

  /**
   * Whether to show labels
   * @default false
   */
  showLabels?: boolean;

  /**
   * Format function for the labels
   */
  formatLabel?: (value: number) => string;

  /**
   * Custom colors for the slider
   */
  colors?: {
    track?: string;
    range?: string;
    thumb?: string;
    tickMarks?: string;
    disabled?: string;
  };

  /**
   * Custom class names for specific elements
   */
  classNames?: {
    root?: string;
    track?: string;
    range?: string;
    thumb?: string;
    tooltip?: string;
    tickMarks?: string;
    labels?: string;
  };

  /**
   * Additional CSS class name for the root element
   */
  className?: string;

  /**
   * Additional inline styles for the root element
   */
  style?: React.CSSProperties;

  /**
   * Inverted slider (right to left or bottom to top)
   * @default false
   */
  inverted?: boolean;

  /**
   * Buffer value for buffered content (e.g., video/audio loading)
   */
  bufferValue?: number;

  /**
   * Whether to show the buffer
   * @default false
   */
  showBuffer?: boolean;

  /**
   * Whether to use a custom thumb component
   */
  customThumb?: React.ReactNode;

  /**
   * Platform-specific styling
   * @default 'default'
   */
  platform?: SliderPlatform;

  /**
   * Additional props to pass to the Radix Slider
   */
  [key: string]: any;
}

// Animation for the thumb
const pulseThumb = keyframes`
  0% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(var(--color-primary-rgb, 59, 130, 246), 0.4);
  }
  70% {
    transform: scale(1.05);
    box-shadow: 0 0 0 6px rgba(var(--color-primary-rgb, 59, 130, 246), 0);
  }
  100% {
    transform: scale(1);
  }
`;

// Animation for value changes
const rangeChange = keyframes`
  0% {
    opacity: 0.7;
  }
  100% {
    opacity: 1;
  }
`;

// Tooltip animation
const tooltipFade = keyframes`
  0% {
    opacity: 0;
    transform: translateY(4px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
`;

// Styled components
const StyledSliderRoot = styled(RadixSlider.Root)<{
  $size: SliderSize;
  $variant: SliderVariant;
  $orientation: SliderOrientation;
  $disabled: boolean;
  $colors: SliderProps['colors'];
  $thumbVisibility: ThumbVisibility;
  $platform?: SliderPlatform;
}>`
  position: relative;
  display: flex;
  align-items: center;
  user-select: none;
  touch-action: none;
  width: 100%;

  /* Orientation styles */
  ${props =>
    props.$orientation === 'horizontal'
      ? css`
          height: ${props.$size === 'sm' ? '24px' : props.$size === 'md' ? '32px' : '40px'};
        `
      : css`
          flex-direction: column;
          width: ${props.$size === 'sm' ? '24px' : props.$size === 'md' ? '32px' : '40px'};
          height: 100%;
          min-height: 100px;
        `}

  /* Platform-specific styles */
  ${props => {
    if (props.$platform === 'spotify') {
      return css`
        &:hover {
          [data-slider-track] {
            background-color: rgba(255, 255, 255, 0.2);
          }

          [data-slider-range] {
            background-color: #1db954;
          }

          [data-slider-thumb] {
            opacity: 1;
            transform: scale(1);
          }
        }
      `;
    }

    if (props.$platform === 'apple') {
      return css`
        height: ${props.$size === 'sm' ? '16px' : props.$size === 'md' ? '20px' : '24px'};
        padding: 0;

        &:hover {
          [data-slider-track] {
            background-color: rgba(0, 0, 0, 0.15);
          }

          [data-slider-thumb] {
            opacity: 1;
            transform: scale(1);
          }
        }
      `;
    }

    if (props.$platform === 'tidal') {
      return css`
        height: ${props.$size === 'sm' ? '18px' : props.$size === 'md' ? '22px' : '26px'};
      `;
    }

    return null;
  }}

  /* Disabled state */
  ${props =>
    props.$disabled &&
    css`
      opacity: 0.6;
      cursor: not-allowed;
    `}

  /* Thumb visibility */
  ${props =>
    props.$thumbVisibility === 'hover' &&
    css`
      &:not(:hover) [data-thumb] {
        opacity: 0;
      }

      &:hover [data-thumb] {
        opacity: 1;
      }
    `}

  ${props =>
    props.$thumbVisibility === 'active' &&
    css`
      [data-thumb] {
        opacity: 0;
      }

      &:active [data-thumb],
      &:focus-within [data-thumb] {
        opacity: 1;
      }
    `}

  ${props =>
    props.$thumbVisibility === 'never' &&
    css`
      [data-thumb] {
        opacity: 0;
      }
    `}
`;

const StyledSliderTrack = styled(RadixSlider.Track)<{
  $size: SliderSize;
  $variant: SliderVariant;
  $orientation: SliderOrientation;
  $colors: SliderProps['colors'];
  $platform?: SliderPlatform;
}>`
  position: relative;
  flex-grow: 1;
  border-radius: 9999px;
  background-color: ${props =>
    props.$colors?.track || 'var(--color-slider-track, rgba(0, 0, 0, 0.1))'};

  /* Size variants */
  ${props =>
    props.$orientation === 'horizontal'
      ? css`
          height: ${props.$size === 'sm' ? '4px' : props.$size === 'md' ? '6px' : '8px'};
        `
      : css`
          width: ${props.$size === 'sm' ? '4px' : props.$size === 'md' ? '6px' : '8px'};
        `}

  /* Platform-specific styles */
  ${props => {
    if (props.$platform === 'spotify') {
      return css`
        height: 4px;
        background-color: rgba(255, 255, 255, 0.1);
        transition: background-color 0.2s ease;
      `;
    }

    if (props.$platform === 'apple') {
      return css`
        height: 3px;
        background-color: rgba(0, 0, 0, 0.1);
        transition: background-color 0.2s ease;
        border-radius: 1.5px;
      `;
    }

    if (props.$platform === 'tidal') {
      return css`
        height: 2px;
        background-color: rgba(255, 255, 255, 0.2);
      `;
    }

    return null;
  }}

  /* Style variants */
  ${props =>
    props.$variant === 'minimal' &&
    css`
      background-color: ${props.$colors?.track ||
      'var(--color-slider-track-minimal, rgba(0, 0, 0, 0.05))'};
      height: ${props.$orientation === 'horizontal' ? '2px' : 'auto'};
      width: ${props.$orientation === 'vertical' ? '2px' : 'auto'};
    `}
`;

const StyledSliderBuffer = styled.div<{
  $size: SliderSize;
  $orientation: SliderOrientation;
  $bufferPercentage: number;
}>`
  position: absolute;
  border-radius: 9999px;
  background-color: var(--color-slider-buffer, rgba(0, 0, 0, 0.15));

  ${props =>
    props.$orientation === 'horizontal'
      ? css`
          height: 100%;
          width: ${props.$bufferPercentage}%;
          left: 0;
          top: 0;
        `
      : css`
          width: 100%;
          height: ${props.$bufferPercentage}%;
