/**
 * Slider component
 *
 * A customizable slider component built on top of Radix UI Slider primitive.
 * Optimized for performance, responsiveness, and extensibility.
 */
export const Slider = React.forwardRef<HTMLDivElement, SliderProps>(
  (
    {
      value,
      onValueChange,
      onValueCommit,
      min = 0,
      max = 100,
      step = 1,
      size = 'md',
      variant = 'default',
      thumbVariant = 'default',
      thumbVisibility = 'always',
      orientation = 'horizontal',
      disabled = false,
      showTooltip = false,
      formatTooltip,
      animate = true,
      optimizePerformance = false,
      showTicks = false,
      tickCount = 5,
      showLabels = false,
      formatLabel,
      colors = {},
      classNames = {},
      className = '',
      style,
      inverted = false,
      bufferValue,
      showBuffer = false,
      customThumb,
      platform,
      ...props
    },
    ref
  ) => {
    // A11y: aria-label/-labelledby describe the thumb(s), not the Radix Root.
    const {
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      ...restProps
    } = props as Record<string, unknown>;
    const [localValue, setLocalValue] = useState<number[]>(value);
    const [isDragging, setIsDragging] = useState<boolean>(false);
    const [isHovering, setIsHovering] = useState<boolean>(false);
    const [activeThumbIndex, setActiveThumbIndex] = useState<number | null>(null);
    const rangeRef = useRef<HTMLDivElement>(null);
    const isRangeChangedRef = useRef<boolean>(false);
    const prevValueRef = useRef<number[]>(value);
    const requestRef = useRef<number | null>(null);
    const tooltipRef = useRef<HTMLDivElement>(null);

    // Calculate buffer percentage
    const bufferPercentage =
      bufferValue !== undefined ? ((bufferValue - min) / (max - min)) * 100 : 0;

    // Handle value changes with optional animation
    useEffect(() => {
      if (JSON.stringify(value) !== JSON.stringify(prevValueRef.current)) {
        if (animate && rangeRef.current) {
          isRangeChangedRef.current = true;
          rangeRef.current.classList.add('slider-range-changed');

          const timer = setTimeout(() => {
            if (rangeRef.current) {
              rangeRef.current.classList.remove('slider-range-changed');
            }
            isRangeChangedRef.current = false;
          }, 300);

          return () => clearTimeout(timer);
        }

        prevValueRef.current = value;
      }

      setLocalValue(value);
    }, [value, animate]);

    // Performance optimization for frequent updates
    const handleValueChange = useCallback(
      (newValue: number[]) => {
        setLocalValue(newValue);

        if (optimizePerformance) {
          if (requestRef.current !== null) {
            cancelAnimationFrame(requestRef.current);
          }

          requestRef.current = requestAnimationFrame(() => {
            onValueChange?.(newValue);
            requestRef.current = null;
          });
        } else {
          onValueChange?.(newValue);
        }
      },
      [onValueChange, optimizePerformance]
    );

    // Clean up any pending animation frames
    useEffect(() => {
      return () => {
        if (requestRef.current !== null) {
          cancelAnimationFrame(requestRef.current);
        }
      };
    }, []);

    // Generate tick marks
    const renderTickMarks = () => {
      const ticks = [];
      const totalTicks = tickCount;

      for (let i = 0; i < totalTicks; i++) {
        const tickValue = min + ((max - min) / (totalTicks - 1)) * i;
        const isActive =
          localValue[0] >= tickValue ||
          (localValue.length > 1 && tickValue <= localValue[1] && tickValue >= localValue[0]);

        ticks.push(
          <TickMark
            key={`tick-${i}`}
            $size={size}
            $active={isActive}
            $colors={colors}
            className={`slider-tick ${isActive ? 'slider-tick-active' : ''} ${classNames.tickMarks || ''}`}
          />
        );
      }

      return (
        <TickMarksContainer $orientation={orientation} className="slider-ticks">
          {ticks}
        </TickMarksContainer>
      );
    };

    // Generate labels
    const renderLabels = () => {
      const labels = [];
      const totalLabels = tickCount;

      for (let i = 0; i < totalLabels; i++) {
        const labelValue = min + ((max - min) / (totalLabels - 1)) * i;
        const isActive =
          localValue[0] >= labelValue ||
          (localValue.length > 1 && labelValue <= localValue[1] && labelValue >= localValue[0]);

        const formattedLabel = formatLabel ? formatLabel(labelValue) : labelValue.toString();

        labels.push(
          <Label
            key={`label-${i}`}
            $active={isActive}
            className={`slider-label ${isActive ? 'slider-label-active' : ''} ${classNames.labels || ''}`}
          >
            {formattedLabel}
          </Label>
        );
      }

      return (
        <LabelsContainer $orientation={orientation} className="slider-labels">
          {labels}
        </LabelsContainer>
      );
    };

    // Calculate tooltip position
    const getTooltipPosition = () => {
      if (activeThumbIndex === null || localValue.length === 0) return 0;

      const thumbValue = localValue[activeThumbIndex];
      return ((thumbValue - min) / (max - min)) * 100;
    };

    // Format tooltip value
    const getTooltipValue = () => {
      if (activeThumbIndex === null || localValue.length === 0) return '';

      const thumbValue = localValue[activeThumbIndex];
      return formatTooltip ? formatTooltip(thumbValue) : thumbValue.toString();
    };

    return (
      <StyledSliderRoot
        ref={ref}
        value={localValue}
        min={min}
        max={max}
        step={step}
        orientation={orientation}
        disabled={disabled}
        dir={inverted ? 'rtl' : 'ltr'}
        onValueChange={handleValueChange}
        onValueCommit={onValueCommit}
        $size={size}
        $variant={variant}
        $orientation={orientation}
        $disabled={disabled}
        $colors={colors}
        $thumbVisibility={thumbVisibility}
        $platform={platform}
        className={`slider ${className} ${classNames.root || ''}`}
        style={style}
        onPointerDown={() => setIsDragging(true)}
        onPointerUp={() => setIsDragging(false)}
        onMouseEnter={() => setIsHovering(true)}
        onMouseLeave={() => setIsHovering(false)}
        {...restProps}
      >
        <StyledSliderTrack
          data-slider-track
          $size={size}
          $variant={variant}
          $orientation={orientation}
          $colors={colors}
          $platform={platform}
          className={`slider-track ${classNames.track || ''}`}
        >
          {showBuffer && bufferValue !== undefined && (
            <StyledSliderBuffer
              $size={size}
              $orientation={orientation}
              $bufferPercentage={bufferPercentage}
              className="slider-buffer"
            />
          )}
          <StyledSliderRange
            data-slider-range
            ref={rangeRef}
            $size={size}
            $variant={variant}
            $orientation={orientation}
            $animate={animate}
            $colors={colors}
            $platform={platform}
            className={`slider-range ${classNames.range || ''}`}
          />
        </StyledSliderTrack>

        {localValue.map((_, i) => (
          <StyledSliderThumb
            key={i}
            data-slider-thumb
            $size={size}
            $variant={variant}
            $thumbVariant={thumbVariant}
            $animate={animate}
            $colors={colors}
            $active={activeThumbIndex === i}
            $platform={platform}
            className={`slider-thumb ${classNames.thumb || ''}`}
            onFocus={() => setActiveThumbIndex(i)}
            onBlur={() => setActiveThumbIndex(null)}
            onPointerDown={() => setActiveThumbIndex(i)}
            onPointerUp={() => !isDragging && setActiveThumbIndex(null)}
            aria-label={
              ariaLabel
                ? `${ariaLabel as string}${localValue.length > 1 ? ` ${i + 1}` : ''}`
                : undefined
            }
            aria-labelledby={ariaLabelledBy as string | undefined}
          >
            {customThumb}
          </StyledSliderThumb>
        ))}

        {showTooltip && isDragging && activeThumbIndex !== null && (
          <StyledTooltip
            ref={tooltipRef}
            $position={getTooltipPosition()}
            $orientation={orientation}
            className={`slider-tooltip ${classNames.tooltip || ''}`}
          >
            {getTooltipValue()}
          </StyledTooltip>
        )}

        {showTicks && renderTickMarks()}
        {showLabels && renderLabels()}
      </StyledSliderRoot>
    );
  }
);

Slider.displayName = 'Slider';

export default Slider;

import React, { useState, useEffect, useRef } from 'react';
import * as Primitive from '@radix-ui/react-primitive';
import styled, { css, keyframes } from 'styled-components';
import type { TimestampVariant, TimestampSize, TimestampFormat } from '@/lib/scilent/types';
import { formatDuration, formatRelativeTime, formatDateTime } from './utils';

export interface TimestampProps {
  /**
   * The value to display, can be:
   * - number (seconds for duration, milliseconds for date)
   * - Date object
   * - ISO string
   */
  value: number | Date | string;

  /**
   * The variant of the timestamp
   * @default 'default'
   */
  variant?: TimestampVariant;

  /**
   * The size of the timestamp
   * @default 'md'
   */
  size?: TimestampSize;

  /**
   * The format to display the timestamp in
   * @default 'duration' for numbers, 'relative' for dates
   */
  format?: TimestampFormat;

  /**
   * Custom format string for date/time (follows Intl.DateTimeFormat options)
   * Only used when format is 'custom'
   */
  customFormat?: Intl.DateTimeFormatOptions;

  /**
   * Custom locale for formatting
   * @default system locale
   */
  locale?: string;

  /**
   * Whether to animate changes
   * @default false
   */
  animate?: boolean;

  /**
   * Whether to update relative times automatically
   * @default true for relative format
   */
  autoUpdate?: boolean;

  /**
   * Update interval in milliseconds for relative times
   * @default 60000 (1 minute)
   */
  updateInterval?: number;

  /**
   * Additional CSS class name
   */
  className?: string;

  /**
   * Additional inline styles for the root element
   */
  style?: React.CSSProperties;
}

